const decode=s=>s.replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(Number(n))).replace(/&nbsp;/g,' ').replace(/&amp;/g,'&');
const labels=['Coupang Trends','Google News Commerce','Google News Seasonal'];
const rows=$input.all().map((i,idx)=>({source:labels[idx]||('source-'+idx),content:typeof i.json==='string'?i.json:JSON.stringify(i.json)}));
const clean=rows.map(r=>({source:r.source,content:decode(r.content).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,3500)}));
const now=new Date(); const end=new Date(now); end.setDate(end.getDate()+84);
const report_date=now.toISOString().slice(0,10), horizon_start=report_date, horizon_end=end.toISOString().slice(0,10), source_text=clean.map(x=>'['+x.source+']\n'+x.content).join('\n\n'); const ollama_body=JSON.stringify({model:'qwen3.5:4b',stream:false,think:false,options:{num_predict:650,temperature:0.15},messages:[{role:'system',content:'당신은 한국 커머스 12주 수요 스카우트다. 900자 이내 한국어로 작성한다. 형식: 1) 향후 12주 중요 일정 2) 현재 계획 적합성 3) 이번 주 조사할 상품 3개 4) 마감 위험. 현재 승인 계획은 가습기 Tool 우선, 이후 온열가전과 Black Friday 가전이다. 제작 2주와 검색 색인 4~8주를 역산한다. 기존 계획을 바꿔야 할 명확한 새 근거가 있을 때만 첫 줄을 [결정필요]로 시작하고, 그렇지 않으면 [계획유지]로 시작한다. 입력자료를 다시 복사하지 말고 판매량이나 수익을 꾸며내지 않는다.'},{role:'user',content:'기준일 '+report_date+' / 범위 '+horizon_start+'~'+horizon_end+'\n'+source_text}]}); return [{json:{report_date,horizon_start,horizon_end,sources:clean,source_text,ollama_body}}];
